"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time
import uuid

from src.order_fulfillment import OrderError, OrderService


_COMMANDS = {"stock", "create", "pay", "cancel", "ship", "get"}


def _write_json(value: dict) -> None:
    sys.stdout.write(
        json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
        + "\n"
    )
    sys.stdout.flush()


def _success(result: object) -> int:
    _write_json({"ok": True, "result": result})
    return 0


def _error(code: str, message: str, details: dict[str, object] | None = None) -> int:
    _write_json(
        {
            "ok": False,
            "error": {
                "code": code,
                "message": message,
                "details": details if details is not None else {},
            },
        }
    )
    return 2


def _storage_error(message: str, details: dict[str, object] | None = None) -> int:
    _write_json(
        {
            "ok": False,
            "error": {
                "code": "STORAGE_ERROR",
                "message": message,
                "details": details if details is not None else {},
            },
        }
    )
    return 3


def _parse_input(line: str) -> dict:
    line = line.strip()
    if line == "":
        return {}
    try:
        value = json.loads(line)
    except json.JSONDecodeError as exc:
        raise OrderError(
            "INVALID_INPUT",
            "Invalid JSON input",
            {"reason": str(exc)},
        ) from exc
    if not isinstance(value, dict):
        raise OrderError(
            "INVALID_INPUT",
            "Input must be a JSON object",
            {"input": value},
        )
    return value


def main() -> int:
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument("--db", required=True)
    parser.add_argument("command")
    args = parser.parse_args()

    if args.command not in _COMMANDS:
        return _error(
            "INVALID_INPUT",
            f"Unknown command: {args.command}",
            {"command": args.command},
        )

    try:
        line = sys.stdin.readline()
        params = _parse_input(line)
    except OrderError as exc:
        return _error(exc.code, exc.message, exc.details)

    try:
        service = OrderService(
            args.db,
            clock=time.time,
            id_factory=lambda: uuid.uuid4().hex,
        )
        with service:
            if args.command == "stock":
                result = service.set_stock(params["sku"], params["quantity"])
            elif args.command == "create":
                result = service.create_order(params["idempotency_key"], params["items"])
            elif args.command == "pay":
                result = service.pay_order(
                    params["order_id"], params["payment_id"], params["amount_cents"]
                )
            elif args.command == "cancel":
                result = service.cancel_order(params["order_id"])
            elif args.command == "ship":
                result = service.ship_order(params["order_id"])
            elif args.command == "get":
                result = service.get_order(params["order_id"])
            else:
                return _error(
                    "INVALID_INPUT",
                    f"Unknown command: {args.command}",
                    {"command": args.command},
                )
        return _success(result)
    except OrderError as exc:
        return _error(exc.code, exc.message, exc.details)
    except Exception as exc:
        return _storage_error(str(exc), {"exception": type(exc).__name__})


if __name__ == "__main__":
    sys.exit(main())

