"""Filesystem-backed delivery spool with durable state updates."""

from __future__ import annotations

import dataclasses
import hmac
import json
import os
import secrets
import sys
import threading
import time
from contextlib import contextmanager
from pathlib import Path
from typing import Any, Callable


@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = details if details is not None else {}

    def __str__(self) -> str:
        return self.message


_PUBLIC_STATUS = {"pending", "leased", "acked", "dead"}


def _canonical_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)


def _validate_finite_number(value: Any, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise SpoolError(
            "INVALID_INPUT",
            f"{name} must be a finite number",
            {name: value},
        )
    if not (-float("inf") < value < float("inf")):
        raise SpoolError(
            "INVALID_INPUT",
            f"{name} must be a finite number",
            {name: value},
        )
    return float(value)


def _non_empty_string(value: Any, name: str) -> str:
    if not isinstance(value, str) or isinstance(value, bool):
        raise SpoolError(
            "INVALID_INPUT",
            f"{name} must be a non-empty string",
            {name: value},
        )
    if value == "" or value.strip() == "":
        raise SpoolError(
            "INVALID_INPUT",
            f"{name} must be a non-empty string",
            {name: value},
        )
    return value


def _validate_payload(value: Any) -> Any:
    """Recursively validate that value is a JSON type and serializable with allow_nan=False."""
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not (-float("inf") < value < float("inf")):
            raise SpoolError(
                "INVALID_INPUT",
                "payload contains non-finite float",
                {"value": value},
            )
        return value
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        return [_validate_payload(v) for v in value]
    if isinstance(value, dict):
        result: dict[str, Any] = {}
        for k, v in value.items():
            if not isinstance(k, str) or isinstance(k, bool):
                raise SpoolError(
                    "INVALID_INPUT",
                    "payload dict keys must be strings",
                    {"key": k},
                )
            result[k] = _validate_payload(v)
        return result
    raise SpoolError(
        "INVALID_INPUT",
        "payload contains unsupported type",
        {"type": type(value).__name__},
    )


def _validate_limits(limits: Any) -> Limits:
    if not isinstance(limits, Limits):
        raise SpoolError(
            "INVALID_INPUT",
            "limits must be a Limits instance",
            {},
        )
    for name, value in dataclasses.asdict(limits).items():
        if name in ("max_messages", "max_payload_bytes", "max_attempts"):
            if isinstance(value, bool) or not isinstance(value, int):
                raise SpoolError(
                    "INVALID_INPUT",
                    f"{name} must be a positive integer",
                    {name: value},
                )
            if value <= 0:
                raise SpoolError(
                    "INVALID_INPUT",
                    f"{name} must be a positive integer",
                    {name: value},
                )
        else:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise SpoolError(
                    "INVALID_INPUT",
                    f"{name} must be a finite non-negative number",
                    {name: value},
                )
            if not (-float("inf") < value < float("inf")) or value < 0:
                raise SpoolError(
                    "INVALID_INPUT",
                    f"{name} must be a finite non-negative number",
                    {name: value},
                )
    if limits.lease_seconds <= 0:
        raise SpoolError(
            "INVALID_INPUT",
            "lease_seconds must be > 0",
            {"lease_seconds": limits.lease_seconds},
        )
    return limits


class _FileLock:
    """Cross-platform exclusive file lock with timeout."""

    def __init__(self, path: Path, timeout: float):
        self.path = path
        self.timeout = timeout
        self._file: Any = None
        self._held = False

    def acquire(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        if sys.platform == "win32":
            self._file = open(self.path, "a+")
            self._file.flush()
            deadline = time.monotonic() + self.timeout
            while True:
                try:
                    import msvcrt
                    self._file.seek(0)
                    msvcrt.locking(self._file.fileno(), msvcrt.LK_NBLCK, 1)
                    self._held = True
                    return
                except OSError:
                    if time.monotonic() >= deadline:
                        self._file.close()
                        self._file = None
                        raise SpoolError(
                            "LOCK_TIMEOUT",
                            "Timed out acquiring lock",
                            {"lock_path": str(self.path)},
                        )
                    time.sleep(0.005)
        else:
            import fcntl
            fd = os.open(str(self.path), os.O_RDWR | os.O_CREAT, 0o666)
            try:
                deadline = time.monotonic() + self.timeout
                while True:
                    try:
                        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                        self._held = True
                        self._file = os.fdopen(fd, "r+")
                        return
                    except BlockingIOError:
                        if time.monotonic() >= deadline:
                            os.close(fd)
                            raise SpoolError(
                                "LOCK_TIMEOUT",
                                "Timed out acquiring lock",
                                {"lock_path": str(self.path)},
                            )
                        time.sleep(0.005)
            except Exception:
                try:
                    os.close(fd)
                except OSError:
                    pass
                raise

    def release(self) -> None:
        if self._file is None:
            return
        try:
            if self._held:
                if sys.platform == "win32":
                    import msvcrt
                    self._file.seek(0)
                    try:
                        msvcrt.locking(self._file.fileno(), msvcrt.LK_UNLCK, 1)
                    except OSError:
                        pass
                else:
                    import fcntl
                    try:
                        fcntl.flock(self._file.fileno(), fcntl.LOCK_UN)
                    except OSError:
                        pass
        finally:
            try:
                self._file.close()
            except OSError:
                pass
            self._file = None
            self._held = False

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.release()


class Spool:
    """Filesystem-backed lease spool."""

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        self._root = Path(root)
        self._clock = clock
        self._limits = _validate_limits(limits)
        self._lock_timeout = _validate_finite_number(lock_timeout, "lock_timeout")
        if self._lock_timeout < 0:
            raise SpoolError(
                "INVALID_INPUT",
                "lock_timeout must be >= 0",
                {"lock_timeout": lock_timeout},
            )
        self._failpoint_func = failpoint
        self._local_lock = threading.Lock()
        self._counter = 0

    def _failpoint(self, name: str) -> None:
        if self._failpoint_func is not None:
            self._failpoint_func(name)

    @property
    def _state_path(self) -> Path:
        return self._root / "state.json"

    @property
    def _lock_path(self) -> Path:
        return self._root / "state.lock"

    def _temp_path(self) -> Path:
        with self._local_lock:
            self._counter += 1
            unique = self._counter
        return self._root / f".state.{os.getpid()}.{unique}.tmp"

    def _now(self) -> float:
        now = self._clock()
        if isinstance(now, bool) or not isinstance(now, (int, float)):
            raise SpoolError(
                "INVALID_DEPENDENCY",
                "clock() returned an invalid type",
                {"clock_output": now},
            )
        if not (-float("inf") < now < float("inf")):
            raise SpoolError(
                "INVALID_DEPENDENCY",
                "clock() returned a non-finite value",
                {"clock_output": now},
            )
        return float(now)

    def _remove_temps(self) -> None:
        pid = os.getpid()
        for path in self._root.glob(f".state.{pid}.*.tmp"):
            try:
                path.unlink()
            except OSError:
                pass

    def _fsync_root(self) -> None:
        try:
            if sys.platform != "win32":
                fd = os.open(str(self._root), os.O_RDONLY)
                try:
                    os.fsync(fd)
                finally:
                    os.close(fd)
        except OSError:
            pass

    def _load_state_text(self, text: str) -> dict:
        try:
            def check_pairs(pairs: list[tuple[str, Any]]) -> dict:
                keys = [k for k, _ in pairs]
                if len(keys) != len(set(keys)):
                    raise SpoolError(
                        "CORRUPT_STATE",
                        "Duplicate JSON keys in state",
                        {},
                    )
                return dict(pairs)

            state = json.loads(text, object_pairs_hook=check_pairs)
        except json.JSONDecodeError as exc:
            raise SpoolError(
                "CORRUPT_STATE",
                "State file contains invalid JSON",
                {"reason": str(exc)},
            ) from exc

        if not isinstance(state, dict):
            raise SpoolError(
                "CORRUPT_STATE",
                "State root must be an object",
                {},
            )

        if set(state.keys()) != {"schema_version", "next_sequence", "messages"}:
            raise SpoolError(
                "SCHEMA_MISMATCH",
                "Unknown or missing top-level state fields",
                {"fields": sorted(state.keys())},
            )

        if state["schema_version"] != 1:
            raise SpoolError(
                "SCHEMA_MISMATCH",
                "Unknown schema version",
                {"schema_version": state["schema_version"]},
            )

        next_sequence = state["next_sequence"]
        if isinstance(next_sequence, bool) or not isinstance(next_sequence, int) or next_sequence < 1:
            raise SpoolError(
                "CORRUPT_STATE",
                "Invalid next_sequence",
                {"next_sequence": next_sequence},
            )

        messages = state["messages"]
        if not isinstance(messages, dict):
            raise SpoolError(
                "CORRUPT_STATE",
                "messages must be an object",
                {},
            )

        max_seq = 0
        for message_id, msg in messages.items():
            if not isinstance(message_id, str):
                raise SpoolError(
                    "CORRUPT_STATE",
                    "Message key must be a string",
                    {},
                )
            self._validate_message(message_id, msg)
            max_seq = max(max_seq, int(msg["sequence"]))

        if next_sequence <= max_seq:
            raise SpoolError(
                "CORRUPT_STATE",
                "next_sequence must be greater than all message sequences",
                {"next_sequence": next_sequence, "max_sequence": max_seq},
            )

        canonical = _canonical_json(state) + "\n"
        if canonical != text:
            raise SpoolError(
                "CORRUPT_STATE",
                "State file is not canonical JSON",
                {},
            )

        return state

    def _validate_message(self, message_id: str, msg: Any) -> None:
        if not isinstance(msg, dict):
            raise SpoolError(
                "CORRUPT_STATE",
                "Message value must be an object",
                {"message_id": message_id},
            )

        public_fields = {"message_id", "payload", "status", "available_at", "sequence", "attempts", "last_error"}
        private_fields = {"lease_token", "worker_id", "expires_at"}
        allowed = public_fields | private_fields
        if not set(msg.keys()).issubset(allowed):
            raise SpoolError(
                "CORRUPT_STATE",
                "Unknown message fields",
                {"message_id": message_id, "fields": sorted(set(msg.keys()) - allowed)},
            )

        if set(msg.keys()) < public_fields:
            raise SpoolError(
                "CORRUPT_STATE",
                "Missing public message fields",
                {"message_id": message_id},
            )

        if msg["message_id"] != message_id:
            raise SpoolError(
                "CORRUPT_STATE",
                "message_id does not match key",
                {"message_id": message_id},
            )

        status = msg["status"]
        if status not in _PUBLIC_STATUS:
            raise SpoolError(
                "CORRUPT_STATE",
                "Invalid message status",
                {"message_id": message_id, "status": status},
            )

        sequence = msg["sequence"]
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
            raise SpoolError(
                "CORRUPT_STATE",
                "Invalid sequence",
                {"message_id": message_id, "sequence": sequence},
            )

        attempts = msg["attempts"]
        if isinstance(attempts, bool) or not isinstance(attempts, int) or attempts < 0:
            raise SpoolError(
                "CORRUPT_STATE",
                "Invalid attempts",
                {"message_id": message_id, "attempts": attempts},
            )

        _validate_finite_number(msg["available_at"], "available_at")

        last_error = msg["last_error"]
        if last_error is not None and (not isinstance(last_error, str) or isinstance(last_error, bool)):
            raise SpoolError(
                "CORRUPT_STATE",
                "last_error must be a string or null",
                {"message_id": message_id},
            )

        has_token = "lease_token" in msg
        has_worker = "worker_id" in msg
        has_expires = "expires_at" in msg

        if status == "leased":
            if not (has_token and has_worker and has_expires):
                raise SpoolError(
                    "CORRUPT_STATE",
                    "Leased message missing private fields",
                    {"message_id": message_id},
                )
            _validate_finite_number(msg["expires_at"], "expires_at")
