                    "CORRUPT_STATE",
                    "Non-leased message contains private fields",
                    {"message_id": message_id},
                )

    def _read_state(self) -> dict:
        if not self._state_path.exists():
            raise SpoolError(
                "NOT_INITIALIZED",
                "Spool has not been initialized",
                {},
            )
        try:
            with open(self._state_path, "r", encoding="utf-8") as f:
                text = f.read()
        except OSError as exc:
            raise SpoolError(
                "CORRUPT_STATE",
                "Failed to read state file",
                {"reason": str(exc)},
