        return self._load_state_text(text)

    def _write_state(self, state: dict) -> None:
        tmp_path = self._temp_path()
        try:
            data = (_canonical_json(state) + "\n").encode("utf-8")
            with open(tmp_path, "wb") as f:
                f.write(data)
                f.flush()
                os.fsync(f.fileno())
            self._failpoint("before_replace")
            os.replace(tmp_path, self._state_path)
            self._failpoint("after_replace")
            self._fsync_root()
        finally:
            self._remove_temps()

    @contextmanager
    def _locked_state(self):
        lock = _FileLock(self._lock_path, self._lock_timeout)
        acquired = False
        try:
            lock.acquire()
            acquired = True
            self._failpoint("after_lock")
            state = self._read_state()
            yield state
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError(
                "INTERNAL_ERROR",
                f"Unexpected error: {exc}",
                {"exception": type(exc).__name__},
            ) from exc
        finally:
            if acquired:
                lock.release()

    @contextmanager
    def _mutation(self):
        with self._locked_state() as state:
            yield state
            self._write_state(state)

    def _public_message(self, msg: dict) -> dict:
        return {
            "message_id": msg["message_id"],
            "payload": msg["payload"],
            "status": msg["status"],
            "available_at": msg["available_at"],
            "sequence": msg["sequence"],
            "attempts": msg["attempts"],
            "last_error": msg["last_error"],
        }

