        validated_payload = _validate_payload(payload)
        canonical_payload = _canonical_json(validated_payload)
        payload_bytes = canonical_payload.encode("utf-8")
        if len(payload_bytes) > self._limits.max_payload_bytes:
            raise SpoolError(
                "INVALID_INPUT",
                "Payload exceeds max_payload_bytes",
                {"size": len(payload_bytes), "max": self._limits.max_payload_bytes},
            )

        if available_at is None:
            available_at_value = self._now()
        else:
            available_at_value = _validate_finite_number(available_at, "available_at")

        with self._mutation() as state:
            messages = state["messages"]
            if message_id in messages:
                existing = messages[message_id]
                if (
                    existing["payload"] == validated_payload
                    and float(existing["available_at"]) == available_at_value
                ):
                    return self._public_message(existing)
