                raise SpoolError(
                    "CAPACITY_EXCEEDED",
                    "Maximum number of messages exceeded",
                    {"max_messages": self._limits.max_messages},
                )

            sequence = state["next_sequence"]
            msg = {
                "message_id": message_id,
                "payload": validated_payload,
                "status": "pending",
                "available_at": available_at_value,
                "sequence": sequence,
                "attempts": 0,
                "last_error": None,
            }
            messages[message_id] = msg
            state["next_sequence"] = sequence + 1
            return self._public_message(msg)

    def claim(self, worker_id: str) -> dict | None:
        worker_id = _non_empty_string(worker_id, "worker_id")
        now = self._now()

        with self._mutation() as state:
            messages = state["messages"]
            candidates = [
                msg
                for msg in messages.values()
                if msg["status"] == "pending" and float(msg["available_at"]) <= now
            ]
            if not candidates:
                return None

            chosen = min(
                candidates,
                key=lambda m: (float(m["available_at"]), int(m["sequence"]), m["message_id"]),
            )
            token = secrets.token_urlsafe(32)
            chosen["status"] = "leased"
            chosen["attempts"] = int(chosen["attempts"]) + 1
            chosen["worker_id"] = worker_id
            chosen["lease_token"] = token
            chosen["expires_at"] = now + float(self._limits.lease_seconds)
            return {**self._public_message(chosen), "lease_token": token}

    def ack(self, message_id: str, lease_token: str) -> dict:
        message_id = _non_empty_string(message_id, "message_id")
        lease_token = _non_empty_string(lease_token, "lease_token")

        with self._mutation() as state:
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError(
                    "NOT_FOUND",
                    "Message not found",
                    {"message_id": message_id},
                )
            msg = messages[message_id]
            if msg["status"] != "leased":
                raise SpoolError(
                    "INVALID_STATE",
                    "Message is not leased",
                    {"message_id": message_id, "status": msg["status"]},
                )
            if not hmac.compare_digest(msg["lease_token"], lease_token):
                raise SpoolError(
                    "UNAUTHORIZED",
                    "Invalid lease token",
                    {"message_id": message_id},
                )
            msg["status"] = "acked"
            msg.pop("worker_id", None)
            msg.pop("lease_token", None)
            msg.pop("expires_at", None)
            return self._public_message(msg)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        message_id = _non_empty_string(message_id, "message_id")
        lease_token = _non_empty_string(lease_token, "lease_token")
        error = _non_empty_string(error, "error")

        with self._mutation() as state:
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError(
                    "NOT_FOUND",
                    "Message not found",
                    {"message_id": message_id},
                )
            msg = messages[message_id]
            if msg["status"] != "leased":
                raise SpoolError(
                    "INVALID_STATE",
                    "Message is not leased",
                    {"message_id": message_id, "status": msg["status"]},
                )
            if not hmac.compare_digest(msg["lease_token"], lease_token):
                raise SpoolError(
                    "UNAUTHORIZED",
                    "Invalid lease token",
                    {"message_id": message_id},
                )

            now = self._now()
            msg["last_error"] = error
            msg.pop("worker_id", None)
            msg.pop("lease_token", None)
            msg.pop("expires_at", None)

            if int(msg["attempts"]) >= self._limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                msg["available_at"] = now + float(self._limits.retry_delay)
            return self._public_message(msg)

    def recover(self) -> dict:
        now = self._now()
        with self._mutation() as state:
            messages = state["messages"]
            count = 0
            for msg in messages.values():
                if msg["status"] == "leased" and float(msg["expires_at"]) <= now:
                    count += 1
                    msg.pop("worker_id", None)
                    msg.pop("lease_token", None)
                    msg.pop("expires_at", None)
                    if int(msg["attempts"]) >= self._limits.max_attempts:
                        msg["status"] = "dead"
                    else:
                        msg["status"] = "pending"
                        msg["available_at"] = now
            return {"recovered": count}

    def get(self, message_id: str) -> dict:
        message_id = _non_empty_string(message_id, "message_id")
        with self._locked_state() as state:
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError(
                    "NOT_FOUND",
                    "Message not found",
                    {"message_id": message_id},
                )
            return self._public_message(messages[message_id])

    def list_messages(self, status=None) -> list[dict]:
        if status is not None and status not in _PUBLIC_STATUS:
            raise SpoolError(
                "INVALID_INPUT",
                "Invalid status filter",
                {"status": status},
            )
        with self._locked_state() as state:
            messages = state["messages"].values()
            if status is not None:
                messages = [m for m in messages if m["status"] == status]
            sorted_messages = sorted(
                messages,
                key=lambda m: (float(m["available_at"]), int(m["sequence"]), m["message_id"]),
            )
            return [self._public_message(m) for m in sorted_messages]

