    sys.stdout.write(
        json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)
        + "\n"
    )
    sys.stdout.flush()


def _success(result: object) -> int:
    _write_json({"ok": True, "result": result})
    return 0


def _error(code: str, message: str, details: dict[str, object] | None = None) -> int:
    _write_json(
        {
            "ok": False,
            "error": {
                "code": code,
                "message": message,
                "details": details if details is not None else {},
            },
        }
    )
    return 2


def _internal_error(code: str, message: str, details: dict[str, object] | None = None) -> int:
    _write_json(
        {
            "ok": False,
            "error": {
                "code": code,
                "message": message,
                "details": details if details is not None else {},
            },
        }
    )
    return 3


def _parse_input(line: str) -> dict:
    line = line.strip()
    if line == "":
        return {}
    try:
        value = json.loads(line)
    except json.JSONDecodeError as exc:
        raise SpoolError(
            "INVALID_INPUT",
            "Invalid JSON input",
            {"reason": str(exc)},
        ) from exc
    if not isinstance(value, dict):
        raise SpoolError(
            "INVALID_INPUT",
            "Input must be a JSON object",
            {"input": value},
        )
    return value


