            available_at = params.get("available_at")
            if available_at is None:
                result = spool.enqueue(params["message_id"], params["payload"])
            else:
                result = spool.enqueue(params["message_id"], params["payload"], available_at)
        elif args.command == "claim":
            result = spool.claim(params["worker_id"])
        elif args.command == "ack":
            result = spool.ack(params["message_id"], params["lease_token"])
        elif args.command == "fail":
            result = spool.fail(params["message_id"], params["lease_token"], params["error"])
        elif args.command == "recover":
            result = spool.recover()
        elif args.command == "show":
            result = spool.get(params["message_id"])
        elif args.command == "list":
            status = params.get("status")
            result = spool.list_messages(status)
        else:
            return _error(
                "INVALID_INPUT",
                f"Unknown command: {args.command}",
                {"command": args.command},
            )
        return _success(result)
    except SpoolError as exc:
        code = _exc_code(exc)
        if code:
            return _internal_error(code, exc.message, exc.details)
        return _error(exc.code, exc.message, exc.details)
    except Exception as exc:
        return _internal_error(
            "INTERNAL_ERROR",
            str(exc),
            {"exception": type(exc).__name__},
        )


if __name__ == "__main__":
    sys.exit(main())

